import{z as i,x as s,o as a,c as t,q as d,j as E,D as o,d as l,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Codex CLI","description":"","frontmatter":{"title":"Codex CLI","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/codex-cli.md","filePath":"llm/codex-cli.md","lastUpdated":1791063341000}'),p={name:"llm/codex-cli.md"};function A(C,e,B,m,x,u){const c=s("Mermaid");return a(),t("div",null,[e[2]||(e[2]=d('<h1 id="codex-cli" tabindex="-1">Codex CLI <a class="header-anchor" href="#codex-cli" aria-label="Permalink to &quot;Codex CLI&quot;">​</a></h1><div class="epigraph"><p>沙箱决定命令碰得到哪些文件与网络；审批策略决定越出边界时要不要停下来问人——两者正交，不要合成一个「自动」开关。</p><footer>—— OpenAI，Codex 官方文档中的 Sandbox / approvals 说明与 openai/codex 仓库</footer></div><p>Codex CLI 是 OpenAI 的本机编程代理：在终端或 IDE 里针对当前仓库计划、编辑与跑命令。官方把它与编辑器扩展、桌面应用、以及 chatgpt.com 上的云端 Codex Web 分开——CLI 跑在你的电脑上，Web 是另一条产品线。配置集中在 <code>~/.codex/config.toml</code>，项目说明书是 <code>AGENTS.md</code>。本篇按官方文档写沙箱、审批与无头执行，默认场景是受信任的自有仓库。不写关闭沙箱去扫主机、也不写绕过审批的利用步骤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把前沿模型接到本地 shell，能力与破坏半径一起到来。只禁止「危险字符串」会被换一种写法绕开；只靠模型「自己小心」则没有强制边界。OpenAI 的拆法是两层策略：<strong>sandbox_mode</strong>（操作系统强制：能读什么、能写哪、能否上网）与 <strong>approval_policy</strong>（策略层：何时暂停等人）。未声明信任的工作区默认偏保守：可以查看与问答，编辑与命令要批准。</p><p>第二个问题是同一代理要服务交互开发与 CI。交互 TUI 需要审批气泡；流水线需要 <code>codex exec</code> 一类非交互入口、稳定的退出码与可解析输出。官方用同一套 config 层叠用户级与项目级，并允许组织在托管机器上用 <code>requirements.toml</code> 禁止 <code>approval_policy = &quot;never&quot;</code> 或 <code>danger-full-access</code>。这把安全默认从「个人偏好」提升为可执行的管理合同。</p><p><span class="marginnote">可以把 sandbox_mode 想成发给代理的门禁卡：哪几扇门刷卡能开，是写死在卡里的；approval_policy 则是遇到没权限的门时，要不要打电话请示。初学者容易找一个「自动程度」总开关，实际上「能做什么」与「何时问人」是两个独立的轴，分开设置才可能出现「能改代码但上网要问」这类组合。</span></p><h3 id="本机、ide、云端不要写混" tabindex="-1">本机、IDE、云端不要写混 <a class="header-anchor" href="#本机、ide、云端不要写混" aria-label="Permalink to &quot;本机、IDE、云端不要写混&quot;">​</a></h3><p>仓库 README 写三条分叉：要在 VS Code / Cursor / Windsurf 里用，装 IDE 扩展；要桌面体验，走 Codex App；要云端代理，去 ChatGPT 的 Codex Web。CLI 是「轻量、跑在你电脑上的编程代理」。模型选择、计费与上下文长度以 developers.openai.com/codex 当时文档为准，本篇不锁某一个快照型号。</p><p><span class="marginnote">安装：macOS/Linux 可用官方 <code>curl</code> 脚本（chatgpt.com/codex/install.sh），也可用 <code>npm i -g @openai/codex</code> 或 Homebrew cask；Windows 有对应 PowerShell 脚本。发布物默认从 <code>releases.openai.com/codex</code> 取，GitHub Releases 作回退。版本与通道以官方文档与仓库发行说明为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动 <code>codex</code> 进入交互；用 <code>/approvals</code> 一类命令改预设。文档给出若干正交组合，而不是单一「自动档」：</p><ul><li>只读浏览：<code>--sandbox read-only</code> 配 <code>--ask-for-approval on-request</code>——可读、答疑；编辑、命令、网络要批。</li><li>CI 只读：只读且 <code>--ask-for-approval never</code>，永不升级权限。</li><li>仓库内编辑：<code>--sandbox workspace-write</code> 配 <code>on-request</code>——工作区内读写与常规命令可自动，出区或上网要批。</li><li><code>--full-auto</code> 预设约等于 workspace-write + on-request。</li><li><code>danger-full-access</code> / <code>--yolo</code> 关掉沙箱与审批，官方标明不推荐，仅当你已在容器或其他隔离里再考虑。</li></ul><p>审批策略还有 <code>untrusted</code>（不在可信集合里的命令先问）与 <code>never</code>（不问）。<code>never</code> 仍可与只读沙箱联用：不问不等于能写全盘。Windows 另有 native sandbox 的 elevated / unelevated 设置。网络默认常关，需要时按审批或配置打开，而不是全局放行。</p>',14)),(a(),E(n,null,{default:o(()=>[r(c,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20SB%7B%22sandbox_mode%22%7D%0A%20%20SB%20--%3E%7Cread-only%7C%20R%5B%22%E5%8F%AA%E8%AF%BB%EF%BC%9A%E7%BC%96%E8%BE%91%E4%B8%8E%E5%91%BD%E4%BB%A4%E9%9C%80%E6%89%B9%22%5D%0A%20%20SB%20--%3E%7Cworkspace-write%7C%20W%5B%22%E5%B7%A5%E4%BD%9C%E5%8C%BA%E5%86%85%E5%8F%AF%E5%86%99%22%5D%0A%20%20SB%20--%3E%7Cdanger-full-access%7C%20F%5B%22%E6%97%A0%20OS%20%E6%B2%99%E7%AE%B1%22%5D%0A%20%20W%20--%3E%20AP%7B%22approval_policy%22%7D%0A%20%20R%20--%3E%20AP%0A%20%20AP%20--%3E%7Con-request%7C%20H%5B%22%E8%B6%8A%E7%95%8C%E5%88%99%E9%97%AE%E4%BA%BA%22%5D%0A%20%20AP%20--%3E%7Cnever%7C%20A%5B%22%E6%8C%89%E6%B2%99%E7%AE%B1%E8%BE%B9%E7%95%8C%E7%9B%B4%E6%8E%A5%E6%89%A7%E8%A1%8C%22%5D%0A%20%20H%20--%3E%20X%5B%22%E5%B7%A5%E5%85%B7%E6%89%A7%E8%A1%8C%22%5D%0A%20%20A%20--%3E%20X%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<h3 id="agents-md-与配置层叠" tabindex="-1">AGENTS.md 与配置层叠 <a class="header-anchor" href="#agents-md-与配置层叠" aria-label="Permalink to &quot;AGENTS.md 与配置层叠&quot;">​</a></h3><p>项目根或子目录放 <code>AGENTS.md</code>，与 <code>~/.codex/AGENTS.md</code> 全局说明层叠，告诉代理构建、测试与风格约定。这与 Claude 的 <code>CLAUDE.md</code>、Gemini 的 <code>GEMINI.md</code> 同构，只是文件名与发现规则以 Codex 文档为准。用户级 <code>~/.codex/config.toml</code> 设默认模型、沙箱、审批、MCP；项目级 <code>.codex/config.toml</code> 仅在项目被信任时加载，且不能覆盖机器本地的提供方、认证、通知与遥测等键——那些必须放在用户级，以免仓库里的配置把代理指到不可信端点。MCP 服务器写在 <code>[mcp_servers]</code>；会话内可用斜杠命令查看状态。</p><p><span class="marginnote">配置层叠的规则类似 CSS 或 <code>.gitignore</code>：越靠近项目的文件优先级越高，但认证、提供方地址这类键被保留给用户级。为什么这条限制如此重要？假如项目级配置能改 <code>openai_base_url</code>，一个恶意仓库就能把你的 API 流量悄悄引到假服务器，窃取密钥与代码——保留键清单本身就是一道供应链防线。</span></p><p>非交互执行走 <code>codex exec</code>（或文档中的无头入口），用于脚本与 CI。官方文档站点（developers.openai.com/codex）覆盖安装、CLI 开关、模型、config 样例与 Agents.md。本篇以该站点与 GitHub <code>openai/codex</code> 为规范，不把第三方长篇指南当作 API 合同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>沙箱是内核/OS 强制的权能集合：即使模型发出「写工作区以外的路径」，执行层也应失败或升级为审批，而不是靠提示词拦。审批是人机接口：把「这一次 / 本会话 / 改执行策略 / 允许某主机 / 拒绝 / 取消整轮」收成显式决定。两者正交，才能表达「可以自动改仓库，但上网必须问」这种日常需求。<code>workspace-write</code> 通常还保护 <code>.git</code> 与 <code>.codex</code> 一类路径，避免代理改自己的策略文件或历史来逃逸——这是完整性，不是功能彩蛋。</p>',6)),(a(),E(n,null,{default:o(()=>[r(c,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%A8%A1%E5%9E%8B%E5%8F%91%E5%87%BA%E4%B8%80%E6%9D%A1%E5%91%BD%E4%BB%A4%22%5D%20--%3E%20S%7B%22OS%20%E6%B2%99%E7%AE%B1%E9%9D%99%E6%80%81%E5%88%A4%E5%AE%9A%22%7D%0A%20%20S%20--%3E%7C%22%E5%9C%A8%E5%85%81%E8%AE%B8%E8%8C%83%E5%9B%B4%E5%86%85%22%7C%20E%5B%22%E7%9B%B4%E6%8E%A5%E6%89%A7%E8%A1%8C%22%5D%0A%20%20S%20--%3E%7C%22%E8%B6%8A%E7%95%8C%EF%BC%9A%E5%87%BA%E5%B7%A5%E4%BD%9C%E5%8C%BA%20%2F%20%E7%BD%91%E7%BB%9C%20%2F%20%E7%B3%BB%E7%BB%9F%E8%B7%AF%E5%BE%84%22%7C%20A%7B%22approval_policy%22%7D%0A%20%20A%20--%3E%7Cnever%7C%20X%5B%22%E6%8B%92%E7%BB%9D%E5%B9%B6%E5%9B%9E%E6%8A%A5%E9%94%99%E8%AF%AF%22%5D%0A%20%20A%20--%3E%7Con-request%7C%20H%5B%22%E6%9A%82%E5%81%9C%EF%BC%8C%E5%BC%B9%E5%87%BA%E5%AE%A1%E6%89%B9%E6%B0%94%E6%B3%A1%22%5D%0A%20%20H%20--%3E%7C%22%E5%85%81%E8%AE%B8%EF%BC%88%E6%9C%AC%E6%AC%A1%20%2F%20%E6%9C%AC%E4%BC%9A%E8%AF%9D%EF%BC%89%22%7C%20E%0A%20%20H%20--%3E%7C%E6%8B%92%E7%BB%9D%7C%20X%0A%20%20E%20--%3E%20O%5B%22%E8%BE%93%E5%87%BA%E5%9B%9E%E7%81%8C%E7%BB%99%E6%A8%A1%E5%9E%8B%EF%BC%8C%E7%BB%A7%E7%BB%AD%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p>AGENTS.md 把团队知识放进文件系统，使模型不必在每一轮对话里重新发现「测试怎么跑」。config 层叠则把组织红线（禁止 never + full access）从个人点点鼠标里抽出来。机制上，Codex CLI 是「模型 + 工具循环 + OS 沙箱 + 审批状态机」；去掉后两段，它就退化成任意命令执行器。</p><p><span class="marginnote">Auto-review 可以把合格的审批请求交给自动评审而不是弹给用户。这是把人从回路里挪走一截，不是缩小沙箱。组织若启用，应单独写进安全评审，不要与 workspace-write 默认混为一谈。</span></p><h3 id="与-claude-code、gemini-cli-的合同差异" tabindex="-1">与 Claude Code、Gemini CLI 的合同差异 <a class="header-anchor" href="#与-claude-code、gemini-cli-的合同差异" aria-label="Permalink to &quot;与 Claude Code、Gemini CLI 的合同差异&quot;">​</a></h3><p>三者都是终端编程代理，都支持 MCP 与项目说明书。Codex 把沙箱模式与审批策略拆成官方一等开关，并在托管配置里允许禁用危险组合。Claude Code 的权限与计划模式写在另一套设置与 Hooks 里。Gemini CLI 开源（Apache 2.0），沙箱与政策引擎有自己的参考页。评测某个模型「在 CLI 里写代码有多好」必须冻结：<strong>哪一个脚手架、哪一档沙箱、是否允许网络</strong>。把 Web 版 Codex 的演示分数写回本机 CLI，会越过产品边界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><code>danger-full-access</code> 与 <code>--yolo</code> 存在，是因为有人已经在隔离虚拟机里跑代理；在日常笔记本上打开等于把本地用户权限交给模型。本篇不讨论如何「尽量自动又尽量广」的组合拳。项目级 config 不能覆盖认证与 <code>openai_base_url</code>，正是为了降低供应链式劫持：恶意仓库不该把流量指到假服务器。</p><p><span class="marginnote">常见误区：「never」只是「不再请示」，不是「权力更大」。<code>--ask-for-approval never</code> 配只读沙箱的代理，依然一个字节都写不进去——请示频率与能力大小互不影响。把它和关沙箱混为一谈，是评测和部署里最常见的配置错误。</span></p><p>CLI、IDE 与 Web 的数据路径、保留政策与网络出口不同。官方文档会演进；开关名以当前 docs 为准。开源仓库含 <code>docs/sandbox.md</code> 与平台实现说明，和网站文档应交叉核对版本。不要用 Codex CLI 对未授权系统做探测；默认信任边界是当前工作区。</p><p><span class="marginnote">出处：OpenAI Codex 文档 <a href="https://developers.openai.com/codex" target="_blank" rel="noreferrer">https://developers.openai.com/codex</a> ；GitHub <code>openai/codex</code> README 与 sandbox 文档；ChatGPT Learn 中的 agent approvals / config 说明。引用写 sandbox_mode 与 approval_policy 两个值，不要只写「自动」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Codex CLI 是本机编程代理，与 IDE 扩展和 Codex Web 分产品线。</li><li>能力边界由沙箱模式与审批策略正交相乘；未信任仓库默认偏只读。</li><li><code>AGENTS.md</code> + <code>config.toml</code> 层叠项目说明与组织红线；项目配置不能改认证与提供方。</li><li><code>--full-auto</code> 仍在 workspace 沙箱内；关掉沙箱属于明确危险预设。</li><li>与其他终端代理比较时必须冻结脚手架与权限档。</li><li>出处：developers.openai.com/codex 与 openai/codex。</li></ul>',11))])}const f=i(p,[["render",A]]);export{_ as __pageData,f as default};
